fn hashv(mut h:u64,v:i64)->u64{for s in (0..64).step_by(8){h=(h^(((v as u64)>>s)&255)).wrapping_mul(0x100000001b3);}h}
fn swap(i:usize,j:usize,ids:&mut[i64;128],ps:&mut[i64;128],pos:&mut[i32;4096]){ids.swap(i,j);ps.swap(i,j);pos[ids[i] as usize]=i as i32;pos[ids[j] as usize]=j as i32;}
fn up(mut i:usize,ids:&mut[i64;128],ps:&mut[i64;128],pos:&mut[i32;4096]){while i>0{let q=(i-1)/2;if ps[i]<=ps[q]{break}swap(i,q,ids,ps,pos);i=q;}}
fn down(mut i:usize,z:usize,ids:&mut[i64;128],ps:&mut[i64;128],pos:&mut[i32;4096]){loop{let mut q=i;let l=2*i+1;let r=l+1;if l<z&&ps[l]>ps[q]{q=l}if r<z&&ps[r]>ps[q]{q=r}if q==i{break}swap(i,q,ids,ps,pos);i=q;}}
#[no_mangle]
pub extern "C" fn generic_heap(a:*const i64,n:usize)->i64{if a.is_null()||n<1||n>769{return -1}let x=unsafe{std::slice::from_raw_parts(a,n)};if x[0]<0||x[0]>256||n!=1+3*x[0] as usize{return -1}let(mut ids,mut ps)=([0i64;128],[0i64;128]);let mut pos=[-1i32;4096];let mut z=0usize;let mut h=0xcbf29ce484222325u64;
for k in 0..x[0] as usize{let(op,id,v)=(x[1+3*k],x[2+3*k],x[3+3*k]);if op==0{if !(0..4096).contains(&id)||!(i32::MIN as i64..=i32::MAX as i64).contains(&v)||pos[id as usize]>=0||z>=128{return -1}ids[z]=id;ps[z]=v;pos[id as usize]=z as i32;up(z,&mut ids,&mut ps,&mut pos);z+=1;}else if op==1||op==2{if id!=0||v!=0||z==0{return -1}let(ri,rv)=(ids[0],ps[0]);if op==2{swap(0,z-1,&mut ids,&mut ps,&mut pos);z-=1;pos[ri as usize]=-1;if z>0{down(0,z,&mut ids,&mut ps,&mut pos)}}h=hashv(hashv(h,ri),rv);}else if op==3{if !(0..4096).contains(&id)||!(i32::MIN as i64..=i32::MAX as i64).contains(&v)||pos[id as usize]<0{return -1}let i=pos[id as usize] as usize;ps[i]=v;up(i,&mut ids,&mut ps,&mut pos);}else if op==4||op==5{if id!=0||v!=0{return -1}h=hashv(h,if op==4{z as i64}else{(z==0) as i64})}else{return -1}}
h as i64}
